//! 🧪️ Neutral UTF8 fragment writes preserve whole input boundaries and reject poisoned output.
use super::*;
use std::fmt::Write;
#[global_allocator]static EXPORT_TEXT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
#[test]fn neutral_fragment_cases_match_portable_and_independent_utf8_bytes(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let mut writer=TextFragment::new(row["capacity"].as_u64().unwrap()as usize).unwrap();for part in row["parts"].as_array().unwrap(){let _=writer.write_str(part.as_str().unwrap());}assert_eq!(writer.written(),row["expected"].as_str().unwrap().as_bytes());assert_eq!(writer.accepted(),row["accepted"].as_bool().unwrap());assert_eq!(writer.finish().is_ok(),row["accepted"].as_bool().unwrap());}assert!(TextFragment::new(8193).is_err());}
#[test]fn formatter_streams_numeric_and_surrogate_plane_fields_into_fixed_backing(){let mut writer=TextFragment::new(8192).unwrap();write!(&mut writer,"{} {:08X} {:.6} {}",'😀',0x10ffff,0.125,false).unwrap();assert_eq!(writer.finish().unwrap(),"😀 0010FFFF 0.125000 false".as_bytes());}
#[test]fn fixed_text_formatting_has_no_system_allocation_or_release(){let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let mut writer=TextFragment::new(8192).unwrap();write!(&mut writer,"{} {:08X} {:.6} {}",'😀',0x10ffff,0.125,false).unwrap();writer.written().len()});assert_eq!(result,28);assert_eq!(physical.requested_bytes,0);assert_eq!(physical.released_bytes,0);assert!(!physical.overflowed);}
